#!/bin/bash
# Count log records and bytes generated by one 100-row insert transaction (cluster idle otherwise).
cd /tmp/rlbench
DEV=rlbench-dev-1
m=$(docker exec $DEV cdb2sql -s --tabs testdb default "select host from comdb2_cluster where is_master='Y'")
lsn() { docker exec $DEV cdb2sql -s --tabs testdb --host $m "exec procedure sys.cmd.send('bdb cluster')" | sed -n "s/.*MASTER.*lsn \([0-9]*\):\([0-9]*\).*/\1 \2/p"; }
python3 - > /tmp/rlbench/scripts/one.sql <<'PY'
import random
r = random.Random(7)
print("insert into t(a,b,c,pad) values " + ",".join("(%d,%d,%d,'%s')" % (9000000000000000000 + i, r.getrandbits(62), r.getrandbits(62), "x"*40) for i in range(100)))
PY
sleep 2
read f1 o1 < <(lsn)
docker exec $DEV cdb2sql -s testdb default -f /scripts/one.sql > /dev/null
sleep 1
read f2 o2 < <(lsn)
echo "lsn $f1:$o1 -> $f2:$o2  bytes=$(( (f2-f1)*41943040 + o2 - o1 )) per-row=$(( ((f2-f1)*41943040 + o2 - o1) / 100 ))"
docker exec $DEV cdb2sql -s --tabs testdb --host $m "select rectype, count(*) from comdb2_transaction_logs('{$f1:$o1}','{$f2:$o2}') group by rectype order by 2 desc" 2>&1 | head -20
